# get_parameter_defaults ----
## Setup ----
data <- FIMS::FIMSFrame(data_big)

## IO correctness ----
test_that("shared defaults retain the recommended values and parameter scales", {
  defaults <- get_parameter_defaults()

  #' @description Test that every supported defaults group has the expected names and values.
  expect_equal(defaults, list(
    Logistic = c(inflection_point = 2, slope = 1),
    DoubleLogistic = c(
      inflection_point_asc = 2, slope_asc = 1,
      inflection_point_desc = 4, slope_desc = 1
    ),
    BevertonHolt = c(
      log_rzero = log(1e6),
      logit_steep = -log(1 - 0.75) + log(0.75 - 0.2),
      log_devs = 0
    ),
    VonBertalanffySchnute = c(
      mean_length_young = 275, mean_length_old = 725,
      growth_coefficient = 0.18, length_weight_a = 2.5e-11,
      length_weight_b = 3, length_sd_young = 28, length_sd_old = 73
    ),
    Population = c(log_M = log(0.2), proportion_female = 0.5),
    Fleet = c(log_q = 0, log_Fmort = -3, survey_log_Fmort = -200),
    Dnorm = c(log_sd = 0.1),
    Dlnorm = c(sd = 0.1, log_sd = log(0.1))
  ))
})

test_that("direct Rcpp constructors use shared parameter starting values", {
  clear()
  withr::defer(clear())
  defaults <- get_parameter_defaults()
  module_groups <- list(
    LogisticSelectivity = "Logistic",
    LogisticMaturity = "Logistic",
    DoubleLogisticSelectivity = "DoubleLogistic",
    BevertonHoltRecruitment = "BevertonHolt",
    VonBertalanffySchnuteGrowth = "VonBertalanffySchnute",
    Population = "Population",
    Fleet = "Fleet",
    DnormDistribution = "Dnorm",
    DlnormDistribution = "Dlnorm"
  )

  for (module_name in names(module_groups)) {
    module <- methods::new(get(module_name, envir = asNamespace("FIMS")))
    module_defaults <- defaults[[module_groups[[module_name]]]]
    fields <- setdiff(
      names(module_defaults),
      c("length_sd_young", "length_sd_old", "survey_log_Fmort", "sd")
    )
    for (field in fields) {
      #' @description Test that each direct constructor uses the shared scalar value and retains constant estimation.
      expect_equal(module[[field]]$size(), 1)
      expect_equal(module[[field]][1][["value"]], module_defaults[[field]])
      expect_equal(
        module[[field]][1][["estimation_type"]]$get(),
        "constant"
      )
    }
  }
})

test_that("R helpers use shared defaults with their existing estimation settings", {
  defaults <- get_parameter_defaults()
  wrapper_groups <- list(
    Logistic = setup_default_Logistic(),
    DoubleLogistic = setup_default_DoubleLogistic(),
    BevertonHolt = setup_default_Recruitment(data),
    Population = setup_default_Population(data, log_init_naa = 1),
    Dnorm = setup_default_DnormDistribution(data = data),
    Dlnorm = setup_default_DlnormDistribution(data = data)
  )
  for (group in names(wrapper_groups)) {
    parameters <- wrapper_groups[[group]]
    for (label in intersect(parameters[["label"]], names(defaults[[group]]))) {
      values <- parameters |>
        dplyr::filter(.data[["label"]] == .env$label) |>
        dplyr::pull(.data[["value"]])
      #' @description Test that wrapper values match the shared values across data-dependent vector lengths.
      expect_equal(values, rep(defaults[[group]][[label]], length(values)))
    }
  }
  #' @description Test that R retains its fixed-effect selectivity and random-effect recruitment settings.
  expect_true(all(wrapper_groups[["Logistic"]][["estimation_type"]] == "fixed_effects"))
  expect_equal(
    wrapper_groups[["BevertonHolt"]] |>
      dplyr::filter(.data[["label"]] == "log_devs") |>
      dplyr::pull(.data[["estimation_type"]]) |>
      unique(),
    "random_effects"
  )
})

## Edge handling ----
test_that("growth reference ages and optional variability remain caller configured", {
  clear()
  withr::defer(clear())
  module <- methods::new(VonBertalanffySchnuteGrowth)
  #' @description Test that shared starting values do not select a mutually exclusive variability path.
  expect_equal(module[["length_at_age_sd_at_reference_ages"]]$size(), 0)
  expect_equal(module[["log_sd_mean_length_young"]]$size(), 0)

  parameters <- setup_default_Growth(data, "VonBertalanffySchnute")
  defaults <- get_parameter_defaults()[["VonBertalanffySchnute"]]
  for (label in intersect(parameters[["label"]], names(defaults))) {
    #' @description Test that scalar growth parameters use shared values.
    expect_equal(
      parameters[["value"]][parameters[["label"]] == label],
      defaults[[label]]
    )
  }
  sd_parameters <- parameters |>
    dplyr::filter(.data[["label"]] == "length_at_age_sd_at_reference_ages")
  #' @description Test that R places shared SD anchors at the data-derived reference ages.
  expect_equal(sd_parameters[["age"]], range(get_ages(data)))
  expect_equal(
    sd_parameters[["value"]],
    unname(defaults[c("length_sd_young", "length_sd_old")])
  )
})

test_that("fleet defaults retain fishing and survey behavior", {
  defaults <- get_parameter_defaults()[["Fleet"]]
  for (fleet in get_fleets(data)) {
    parameters <- setup_default_Fleet(data, fleet)
    fleet_types <- get_data(data) |>
      dplyr::filter(.data[["fleet"]] == .env$fleet) |>
      dplyr::pull(.data[["type"]])
    has_index <- "index" %in% fleet_types
    expected <- defaults[[if (has_index) "survey_log_Fmort" else "log_Fmort"]]
    #' @description Test that R chooses the correct shared mortality for each fleet's observations.
    expect_true(all(
      parameters[["value"]][parameters[["label"]] == "log_Fmort"] == expected
    ))
  }
})

test_that("shared defaults have no module-registry or mutable global state", {
  clear()
  withr::defer(clear())
  first_module <- methods::new(LogisticSelectivity)
  defaults <- get_parameter_defaults()
  defaults[["Logistic"]][["slope"]] <- 99
  setup_default_parameters(data)
  second_module <- methods::new(LogisticSelectivity)
  #' @description Test that retrieving defaults and generating a parameter tibble do not create modules.
  expect_equal(second_module$get_id(), first_module$get_id() + 1)
  expect_equal(get_parameter_defaults()[["Logistic"]][["slope"]], 1)

  second_module[["slope"]][1][["value"]] <- 7
  #' @description Test that explicit Rcpp and R helper overrides remain supported and instance-local.
  expect_equal(second_module[["slope"]][1][["value"]], 7)
  expect_equal(first_module[["slope"]][1][["value"]], 1)
  expect_true(all(
    setup_default_Population(
      data,
      log_M = log(0.3), log_init_naa = 5, proportion_female = 0.7
    )[["value"]] %in% c(log(0.3), 5, 0.7)
  ))
  expect_equal(
    setup_default_DlnormDistribution(value = 0.4, data = data)[["value"]],
    rep(log(0.4), get_n_years(data))
  )
})
